/**
 * Port of `st_core::normalize` — MUST stay byte-for-byte identical to the Rust version,
 * otherwise a secret registered from the browser never matches a scan.
 * `normalize.test.ts` checks it against `testdata/digest_vectors.json`, which was
 * generated by an independent implementation.
 *
 * Rust semantics reproduced here:
 * - `char::is_ascii_whitespace` = U+0020, U+0009, U+000A, U+000C, U+000D (not U+000B);
 * - `str::len()` counts UTF-8 bytes, `chars().count()` counts Unicode scalar values;
 * - `str::lines()` splits on `\n` and drops one trailing `\r` per line.
 */
import { type SecretType, isKeyMaterial } from "./secretTypes";

export const MIN_SECRET_LEN = 6;
export const MAX_SECRET_LEN = 16 * 1024;

export type NormalizeError = "empty" | "too_short" | "too_long" | "contains_nul" | "multi_line" | "malformed_pem";

export class NormalizeFailure extends Error {
  constructor(readonly code: NormalizeError) {
    super(code);
    this.name = "NormalizeFailure";
  }
}

const encoder = new TextEncoder();

const isAsciiWs = (c: string): boolean => c === " " || c === "\t" || c === "\n" || c === "\f" || c === "\r";

export function utf8Len(s: string): number {
  return encoder.encode(s).length;
}

export function charCount(s: string): number {
  let n = 0;
  for (const _ of s) n++;
  return n;
}

function trim(s: string): string {
  let start = 0;
  let end = s.length;
  while (start < end && isAsciiWs(s[start] as string)) start++;
  while (end > start && isAsciiWs(s[end - 1] as string)) end--;
  return s.slice(start, end);
}

function rustLines(s: string): string[] {
  if (s === "") return [];
  const parts = s.split("\n");
  // A trailing "\n" does not produce an empty last line.
  if (parts[parts.length - 1] === "") parts.pop();
  return parts.map((l) => (l.endsWith("\r") ? l.slice(0, -1) : l));
}

const isBase64Char = (c: string): boolean => /^[A-Za-z0-9+/=]$/.test(c);
const allBase64 = (s: string): boolean => [...s].every(isBase64Char);

function pemBody(raw: string): string {
  const unescaped = raw.replaceAll("\\r\\n", "\n").replaceAll("\\n", "\n");
  const lines = rustLines(unescaped).map(trim);
  const begin = lines.findIndex((l) => l.startsWith("-----BEGIN ") && l.endsWith("-----"));
  if (begin < 0) throw new NormalizeFailure("malformed_pem");
  let body = "";
  let closed = false;
  for (const line of lines.slice(begin + 1)) {
    if (line.startsWith("-----END ")) {
      closed = true;
      break;
    }
    // Encapsulated headers of legacy encrypted keys (Proc-Type, DEK-Info).
    if (line === "" || line.includes(":")) continue;
    if (!allBase64(line)) throw new NormalizeFailure("malformed_pem");
    body += line;
  }
  if (!closed || body === "") throw new NormalizeFailure("malformed_pem");
  return body;
}

function opensshPublicBlob(raw: string): string | null {
  const parts = trim(raw)
    .split(/[ \t\n\f\r]+/)
    .filter((p) => p !== "");
  const [algo, blob] = parts;
  if (algo === undefined || blob === undefined) return null;
  const knownAlgo =
    algo.startsWith("ssh-") || algo.startsWith("ecdsa-sha2-") || algo.startsWith("sk-ssh-") || algo.startsWith("sk-ecdsa-");
  return knownAlgo && blob.startsWith("AAAA") && allBase64(blob) ? blob : null;
}

function checkLen(s: string): void {
  if (s === "") throw new NormalizeFailure("empty");
  if (utf8Len(s) > MAX_SECRET_LEN) throw new NormalizeFailure("too_long");
  if (charCount(s) < MIN_SECRET_LEN) throw new NormalizeFailure("too_short");
}

/** Canonical form of `raw` for `type`. Throws `NormalizeFailure`. */
export function normalize(type: SecretType, raw: string): string {
  if (raw.includes("\0")) throw new NormalizeFailure("contains_nul");
  if (utf8Len(raw) > MAX_SECRET_LEN * 2) throw new NormalizeFailure("too_long");

  let canonical: string;
  const blob = type === "ssh_key" ? opensshPublicBlob(raw) : null;
  if (isKeyMaterial(type) && raw.includes("-----BEGIN ")) {
    canonical = pemBody(raw);
  } else if (blob !== null) {
    canonical = blob;
  } else {
    const trimmed = trim(raw);
    if (trimmed.includes("\n") || trimmed.includes("\r")) throw new NormalizeFailure("multi_line");
    canonical = trimmed;
  }
  checkLen(canonical);
  return canonical;
}

export const NORMALIZE_MESSAGES: Record<NormalizeError, string> = {
  empty: "Значение пустое",
  too_short: `Значение короче ${MIN_SECRET_LEN} символов`,
  too_long: `Значение длиннее ${MAX_SECRET_LEN} байт`,
  contains_nul: "Значение содержит NUL-байт",
  multi_line: "Перенос строки допустим только в ключах и сертификатах (PEM)",
  malformed_pem: "Повреждённый PEM-блок: нужен BEGIN, base64-тело и END",
};
